function PVPArenaRivalGroupNode:RefreshUI()
    -----------------------------
    --- 初始化数据
    local pvpArenaDojo      = self.pvpArenaDojo
    local mainPanelStatus   = pvpArenaComponent:GetMainPanelStatus()
    self.Txttitle.text = TextConf[mainPanelStatus]

    local hex = mainPanelStatus == Constants.PVPArenaMainPanelStatus.Ready and "#acacac" or "#ffffff"
    self.Txttitle.color = XLuaUtils.HexToColor(hex)

    local seasonFlag = pvpArenaComponent:GetSeasonFlag()
    local curWheel = pvpArenaComponent:GetCurWheel()
    local finalWheelCount = pvpArenaComponent:GetFinalWheelCount()
    local finalDisplayWheel = finalWheelCount + 1
    local isClose = Constants.PVPArenaMainPanelStatus.Closed == mainPanelStatus
    local playerInfo, playerId
    if isClose or (seasonFlag == Constants.PVPArenaSeasonFullStatus.Final and curWheel == finalDisplayWheel) then
        --- 关闭  对阵图数据 是 正常对战情况 外加 第三和第四两条是数据 直接去对阵图倒数三条数据
        local endNum = pvpArenaComponent:GetFinalEndNumber()
        local map = checkTable(pvpArenaDojo.map)
        local positionData = map[tostring(endNum)] or {}
        local matcherInfo     = pvpArenaDojo.matcherInfo or {}
        playerInfo = matcherInfo[tostring(positionData.playerId)]
    --- 匹配不处理 匹配中表示没数据
    --elseif Constants.PVPArenaMainPanelStatus.InMatch == mainPanelStatus then
    elseif Constants.PVPArenaMainPanelStatus.InBattle == mainPanelStatus then
        playerInfo, playerId = pvpArenaComponent:CalcRivalInfoByWheel(curWheel)
        --- 有可能还没打完 到上一轮找
        if playerInfo == nil then
            playerInfo, playerId = pvpArenaComponent:CalcRivalInfoByWheel(curWheel - 1)
        end
    elseif Constants.PVPArenaMainPanelStatus.InWait == mainPanelStatus or Constants.PVPArenaMainPanelStatus.Ready == mainPanelStatus then
        playerInfo, playerId = pvpArenaComponent:CalcRivalInfoByWheel(curWheel)
    end

    local isHidePlayerInfo = playerInfo == nil
    local name, level
    if isHidePlayerInfo then
        name = "--------------------"
        level = "------"
    else
        local excludeDialogs = {
            -- {id = Constants.UITypeIds.PVPArenaMain}
        }
        PVPArenaUtils.RefreshPlayerHeadNode(self.PlayerHeadNode.gameObject, playerId, playerInfo, excludeDialogs)
        name = playerInfo.name
        level = localize("<size=16>LV</size>_num_", {_num_ = playerInfo.level})
    end

    self.playerId = playerId
    self.playerInfo = playerInfo
    -----------------------------
    --- 刷新UI
    KTool.SetActive(self.ImgBattle.gameObject, not isClose)
    KTool.SetActive(self.checkGroup.gameObject, not isClose)
    KTool.SetActive(self.RankFlagNode.gameObject, isClose)
    KTool.SetActive(self.EmptyHeadNode.gameObject, isHidePlayerInfo)
    KTool.SetActive(self.ImgCheckIcon.gameObject, not isHidePlayerInfo)
    KTool.SetActive(self.Txtcheck.gameObject, not isHidePlayerInfo)
    KTool.SetActive(self.PlayerHeadNode.gameObject, not isHidePlayerInfo)

    self.TxtPlayerName.text = name
    self.TxtLV.text = level

end

