function PVPArenaRivalGroupNode:OnClickLookAreaAction()
    if self.playerId == nil then return end

    local excludeDialogs = {
        -- {id = Constants.UITypeIds.PVPArenaMain}
    }
    PVPArenaUtils.ShowMatcherInfoDialog(self.playerId, self.playerInfo, excludeDialogs)
end

